select count(l1_0.id) from listing l1_0 left join category c1_0 on c1_0.id=l1_0.category_id where l1_0.deleted_at is null and l1_0.status='ON_SALE' and l1_0.moderation_status in ('NORMAL','WARNING_ACK_REQUIRED') and (lower(l1_0.title) like '%galaxy%' escape '' or lower(c1_0.name) like '%galaxy%' escape '' or lower(c1_0.manufacturer) like '%galaxy%' escape '') and 1=1 and 1=1 and 1=1 and 1=1 and 1=1 and 1=1 and 1=1;
